<?php require_once __DIR__.'/includes/auth.php';require_user();$uid=(int)$_SESSION['user_id'];$s=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE user_id=? AND status='valid'");$s->execute([$uid]);$total=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? AND r.status='valid' AND e.event_date>=CURDATE()");$s->execute([$uid]);$upcoming=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM registrations r JOIN checkins c ON c.registration_id=r.id WHERE r.user_id=?");$s->execute([$uid]);$attended=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT r.*,e.title,e.event_date,e.start_time,e.venue,e.image_url,e.status event_status,c.checked_in_at FROM registrations r JOIN events e ON e.id=r.event_id LEFT JOIN checkins c ON c.registration_id=r.id WHERE r.user_id=? AND r.status='valid' ORDER BY e.event_date DESC LIMIT 5");$s->execute([$uid]);$regs=$s->fetchAll();$pageTitle='My dashboard';require __DIR__.'/includes/header.php'; ?>
<section class="section section-soft"><div class="container"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><span class="eyebrow">Participant workspace</span><h1 class="mt-3">Welcome, <?=e($_SESSION['user_name'])?> 👋</h1><p class="muted mb-0">Your registrations and tickets, all together.</p></div><a href="events.php" class="btn btn-primary">Explore events <i class="bi bi-arrow-right ms-1"></i></a></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><span class="stat-icon"><i class="bi bi-ticket"></i></span><div class="stat-value mt-3"><?=$total?></div><div class="muted">Total registrations</div></div></div><div class="col-md-4"><div class="stat-card"><span class="stat-icon"><i class="bi bi-calendar-event"></i></span><div class="stat-value mt-3"><?=$upcoming?></div><div class="muted">Upcoming events</div></div></div><div class="col-md-4"><div class="stat-card"><span class="stat-icon"><i class="bi bi-check2-circle"></i></span><div class="stat-value mt-3"><?=$attended?></div><div class="muted">Events checked in</div></div></div></div><div class="panel"><div class="section-head mb-3"><div><h2 class="h4">Your recent tickets</h2><p class="muted mb-0">Open a ticket anytime from here.</p></div><a href="my-events.php">View all <i class="bi bi-arrow-right"></i></a></div><?php if(!$regs): ?><div class="empty-state"><i class="bi bi-calendar2-plus fs-1"></i><h3 class="h5 mt-3">Your event journey starts here</h3><p>You haven't registered for an event yet.</p><a class="btn btn-primary" href="events.php">Find an event</a></div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Check-in</th><th></th></tr></thead><tbody><?php foreach($regs as $r): ?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e(date('M j, Y',strtotime($r['event_date'])))?></td><td><?=e($r['venue'])?></td><td><span class="status-pill <?=$r['checked_in_at']?'status-checked':'status-pending'?>"><?=$r['checked_in_at']?'Checked in':'Not checked in'?></span></td><td><a class="btn btn-sm btn-outline-primary" href="ticket.php?id=<?=(int)$r['id']?>">View ticket</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
